import java.util.*;
import java.io.*;

public class MaxFlowSolver {
    static class Edge {
        int from, to;
        long flow, capacity;
        public Edge(int from, int to, long flow, long capacity) {
            this.from = from;
            this.to = to;
            this.flow = flow;
            this.capacity = capacity;
        }
    }

    static class MaxFlow {
        int s, t;
        List<Edge> edges = new ArrayList<>();
        List<Integer>[] graph = new ArrayList[7100];
        int[] dist = new int[7100];
        int[] visited = new int[7100];
        int[] current = new int[7100];

        public MaxFlow() {
            for (int i = 0; i < 7100; i++) {
                graph[i] = new ArrayList<>();
            }
        }

        void initialize() {
            edges.clear();
            for (int i = 0; i < 7100; i++) {
                graph[i].clear();
            }
        }

        void addEdge(int from, int to, long cap) {
            Edge e1 = new Edge(from, to, 0, cap);
            Edge e2 = new Edge(to, from, 0, 0);
            edges.add(e1);
            edges.add(e2);
            graph[from].add(edges.size() - 2);
            graph[to].add(edges.size() - 1);
        }

        boolean buildLevelGraph() {
            Arrays.fill(visited, 0);
            Arrays.fill(dist, 0);
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            visited[s] = 1;
            dist[s] = 0;
            while (!q.isEmpty()) {
                int v = q.poll();
                for (int i : graph[v]) {
                    Edge e = edges.get(i);
                    int nxt = e.to;
                    if (visited[nxt] == 0 && e.capacity > e.flow) {
                        dist[nxt] = dist[v] + 1;
                        q.offer(nxt);
                        visited[nxt] = 1;
                    }
                }
            }
            return visited[t] == 1;
        }

        long sendFlow(int u, long flow) {
            if (u == t || flow == 0) return flow;
            long totalFlow = 0;
            for (int i = current[u]; i < graph[u].size(); i++) {
                int idx = graph[u].get(i);
                Edge e = edges.get(idx);
                if (dist[u] + 1 == dist[e.to]) {
                    long pushed = sendFlow(e.to, Math.min(flow, e.capacity - e.flow));
                    if (pushed > 0) {
                        e.flow += pushed;
                        edges.get(idx ^ 1).flow -= pushed;
                        totalFlow += pushed;
                        flow -= pushed;
                        if (flow == 0) break;
                    }
                }
                current[u]++;
            }
            return totalFlow;
        }

        long maxFlow() {
            long total = 0;
            while (buildLevelGraph()) {
                Arrays.fill(current, 0);
                total += sendFlow(s, Long.MAX_VALUE);
            }
            return total;
        }
    }

    static char[][] grid1 = new char[14][14];
    static char[][] grid2 = new char[14][14];
    static boolean[][] visitedCells = new boolean[14][14];
    static int[][] distanceMap = new int[14][14];
    static int n;
    static int[] target = new int[103];

    static void performBFS(int x, int y, int n, char[][] grid1, boolean[][] visitedCells, int[][] distanceMap) {
        for (int i = 0; i < 14; i++) {
            Arrays.fill(distanceMap[i], 111);
        }
        Queue<int[]> q = new LinkedList<>();
        distanceMap[x][y] = 0;
        q.offer(new int[]{x, y});
        int[] dx = {1, 0, 0, -1};
        int[] dy = {0, 1, -1, 0};
        while (!q.isEmpty()) {
            int[] p = q.poll();
            int cx = p[0], cy = p[1], distVal = distanceMap[cx][cy];
            if (visitedCells[cx][cy]) continue;
            visitedCells[cx][cy] = true;
            for (int dir = 0; dir < 4; dir++) {
                int nx = cx + dx[dir], ny = cy + dy[dir];
                if (nx <= 0 || nx > n || ny <= 0 || ny > n || visitedCells[nx][ny] || grid1[nx][ny] == 'Y') continue;
                distanceMap[nx][ny] = distVal + 1;
                q.offer(new int[]{nx, ny});
            }
        }
    }

    static int getIndex(int level, int x, int y, int n) {
        return level * n * n + (x - 1) * n + y;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        int t = Integer.parseInt(st.nextToken());

        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                grid1[i][j] = line.charAt(j - 1);
