                for (int k = 1; k <= n; k++) {
                    if (grid1[j][k] == 'Y' || grid1[j][k] == 'Z') continue;
                    for (int l = 0; l < 4; l++) {
                        int tx = j + dx[l], ty = k + dy[l];
                        if (tx >= 1 && tx <= n && ty >= 1 && ty <= n && grid1[tx][ty] != 'Y' && grid1[tx][ty] != 'Z') {
                            if (distanceMap[j][k] >= i && distanceMap[tx][ty] >= i) {
                                mf.addEdge(getIndex(i - 1, tx, ty, n), getIndex(i, j, k, n), Long.MAX_VALUE);
                            }
                        }
                    }
                    mf.addEdge(getIndex(i, j, k, n), target[getIndex(0, j, k, n)], Long.MAX_VALUE);
                }
            }
        }

        System.out.println(mf.maxFlow());
    }
}
